admin_templates.template:
.FilterList .allow span { background-image: url('{xen:property imagePath}/xenforo/permissions/allow.png') !important; }
.FilterList .revoke span { background-image: url('{xen:property imagePath}/xenforo/permissions/revoke.png') !important; }
.FilterList a .spamDate { padding-top: 3px; float: right; text-align: right; }
.FilterList .passed h4 { background-color: {xen:property secondaryLightest}; }

.spamHint { font-size: 11px; color: #969696; margin-left: 10px; margin-top: 2px; }

phrases.phrase:
This is your daily summary of unconfirmed accounts on {board_title}.

The following users have been deleted:
{usersEnd}

The following users have been emailed; they have {daysTwo} days left:
{usersTwo}

The following users have been emailed; they have {daysOne} days left:
{usersOne}

The following users are also unconfirmed, but have not been emailed:
{usersNon}

{username},
It has been {days} days since you registered your account at {board_title}. If you do not confirm your account within the next {left} days, it will automatically be deleted.
In order to complete your registration, you need confirm your account by following the page below.
{confirm_link}
Thanks for registering, {board_title}

templates.template:
.downVotes { float: right; }

.voteList .primaryContent .users { text-align: right; float: right; margin-left: 10px; }
.voteList .primaryContent .avatar img { width: 24px; height: 24px; }

.modList { text-align: right; }

.staffList .staffActivity{ float: right; padding: 10px; font-size: 11px; }
.staffList .staffUser { position: relative; display: inline-block; width: 180px; }
.staffList .staffUser .userInfo { margin-left: 35px; padding: 10px; }
.staffList .avatar { float: left; }
.staffList .avatar img { height: 30px; width: 30px; }
.staffVerbose .staffUser { float: left; }
.staffVerbose .contentInfo { margin: 0px 0px 0px 200px; padding: 10px; border-bottom: 1px solid {xen:property primaryLighterStill}; }
{xen:helper clearfix, '.staffList .staffVerbose'}

.copyright { text-align: center; font-size: 11px; margin: 10px; }

.bbCodeBlock.bbCodeNotice
{
	border-color: #990000 !important;
}

.bbCodeBlock.bbCodeNotice .attribution
{
	color: #EBEBEB !important;
	background: #990000 url('{xen:property imagePath}/xenforo/gradients/category-23px-light.png') repeat-x top !important;
	border-bottom: 1px solid #990000 !important;
}

.bbCodeBlock.bbCodeNotice .attribution b { font-size: 19px; }
